package com.gridscape.icons;

import com.gridscape.constants.TaskTypes;
import java.util.Map;

/** Resolves classpath resource paths for boss and task-type icons. */
public final class IconResolver
{
	private IconResolver() {}

	public static String resolveBossIconPath(String bossId)
	{
		if (bossId == null || bossId.trim().isEmpty()) return null;
		String id = bossId.trim();
		String filename = IconResources.BOSS_ICON_OVERRIDES.get(id);
		if (filename == null)
			filename = "game_icon_" + id.replace("_", "") + ".png";
		return IconResources.BOSS_ICONS_RESOURCE_PREFIX + filename;
	}

	/** Full classpath path for an area unlock tile id, or null if unmapped. */
	public static String resolveAreaIconPath(String areaId)
	{
		if (areaId == null || areaId.isEmpty()) return null;
		String id = areaId.trim();
		String filename = IconResources.AREA_ICON_FILENAME.get(id);
		if (filename == null)
		{
			for (Map.Entry<String, String> e : IconResources.AREA_ICON_FILENAME.entrySet())
			{
				if (e.getKey() != null && e.getKey().equalsIgnoreCase(id))
				{
					filename = e.getValue();
					break;
				}
			}
		}
		if (filename == null) return null;
		return IconResources.AREA_ICONS_RESOURCE_PREFIX + filename;
	}

	public static String resolveTaskTypeLocalIconPath(String taskType)
	{
		if (taskType == null) return null;
		String t = TaskTypes.normalizeToCanonical(taskType).trim();
		if (t.isEmpty()) return null;

		// Fast path: exact key (most tasks.json values match UI case)
		String fn = IconResources.TASK_TYPE_LOCAL_ICON.get(t);
		if (fn != null) return IconResources.TASK_ICONS_RESOURCE_PREFIX + fn;

		// Robust path: ignore-case match (covers tasks.json/user edits with different casing)
		for (Map.Entry<String, String> e : IconResources.TASK_TYPE_LOCAL_ICON.entrySet())
		{
			String key = e.getKey();
			if (key != null && key.equalsIgnoreCase(t))
				return IconResources.TASK_ICONS_RESOURCE_PREFIX + e.getValue();
		}
		return null;
	}

	/**
	 * Full path for a task tile: if {@code bossId} is set (and type is not Collection Log), boss icon; else task-type map;
	 * {@code killCount} without boss uses combat icon; then collection log / clue heuristics from type or display name.
	 * Collection Log tasks keep the collection log tile icon even when {@code bossId} identifies the entry's boss.
	 */
	public static String resolveTaskTileLocalIconPath(String taskType, String displayName, String bossId)
	{
		if (bossId != null && !bossId.trim().isEmpty() && !TaskTypes.isCollectionLogType(taskType))
		{
			String bossPath = resolveBossIconPath(bossId.trim());
			if (bossPath != null) return bossPath;
		}

		if (taskType != null)
		{
			String tt = taskType.trim();
			if (TaskTypes.KILL_COUNT.equalsIgnoreCase(tt))
			{
				String combat = resolveTaskTypeLocalIconPath(TaskTypes.COMBAT);
				if (combat != null) return combat;
			}
		}

		String byType = resolveTaskTypeLocalIconPath(taskType);
		if (byType != null) return byType;

		if (isCollectionLogHint(taskType, displayName))
			return IconResources.TASK_ICONS_RESOURCE_PREFIX + "Collection_log_detail.png";
		if (isClueHint(taskType, displayName))
			return IconResources.TASK_ICONS_RESOURCE_PREFIX + "Clue_scroll_v1.png";
		return null;
	}

	private static boolean isCollectionLogHint(String taskType, String displayName)
	{
		if (TaskTypes.isCollectionLogType(taskType)) return true;
		return displayName != null && displayName.toLowerCase().contains("collection log");
	}

	private static boolean isClueHint(String taskType, String displayName)
	{
		if (TaskTypes.isClueType(taskType)) return true;
		return displayName != null && displayName.toLowerCase().contains("clue scroll");
	}

	public static boolean isCollectionLogTask(String taskType, String displayName)
	{
		if (TaskTypes.isCollectionLogType(taskType)) return true;
		return displayName != null && displayName.toLowerCase().contains("collection log");
	}

	public static boolean isEquipTask(String displayName)
	{
		return displayName != null && (displayName.toLowerCase().startsWith("equip a ")
			|| displayName.toLowerCase().startsWith("equip an "));
	}

	public static String extractEquipItemName(String displayName)
	{
		if (displayName == null) return null;
		String d = displayName.trim();
		if (d.toLowerCase().startsWith("equip an "))
			return d.substring(9).trim();
		if (d.toLowerCase().startsWith("equip a "))
			return d.substring(8).trim();
		return null;
	}

	public static boolean isIconMatchCombatSize(String taskType, String displayName)
	{
		if (taskType != null)
		{
			if (TaskTypes.QUEST.equalsIgnoreCase(taskType)) return true;
			if (TaskTypes.isAchievementDiaryType(taskType)) return true;
		}
		return isCollectionLogTask(taskType, displayName);
	}
}

package com.gridscape.icons;

import com.gridscape.GridScapePlugin;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import net.runelite.client.util.ImageUtil;

/** Load and scale icons from plugin classpath resources. */
public final class IconCache
{
	private static final Map<String, BufferedImage> rawTaskIconCache = new ConcurrentHashMap<>();

	private IconCache() {}

	public static BufferedImage loadWithFallback(String primaryPath, String fallbackPath)
	{
		BufferedImage img = load(primaryPath);
		if (img != null) return img;
		return load(fallbackPath);
	}

	/**
	 * RuneLite {@link ImageUtil#loadImageResource(Class, String)} treats paths without a leading {@code '/'}
	 * as relative to the class's package ({@code com/gridscape/}), which breaks resources under
	 * {@code /com/taskIcons/}, {@code /com/bossicons/}, etc. Classpath-root resources must keep the leading slash.
	 */
	private static BufferedImage load(String path)
	{
		if (path == null || path.isEmpty()) return null;
		String p = path;
		if (!p.startsWith("/") && p.startsWith("com/"))
			p = "/" + p;
		try
		{
			return ImageUtil.loadImageResource(GridScapePlugin.class, p);
		}
		catch (Exception e)
		{
			return null;
		}
	}

	public static BufferedImage loadRawTaskIcon(String taskType, String displayName, String bossId)
	{
		String path = IconResolver.resolveTaskTileLocalIconPath(taskType, displayName, bossId);
		if (path == null) return null;
		return rawTaskIconCache.computeIfAbsent(path, p -> loadWithFallback(p, IconResources.GENERIC_TASK_ICON));
	}

	public static BufferedImage loadDefaultTaskIcon()
	{
		return loadWithFallback(IconResources.GENERIC_TASK_ICON,
			IconResources.TASK_ICONS_RESOURCE_PREFIX + "Other_icon.png");
	}

	/** Largest dimension of Combat icon scaled to {@code iconMaxFit} (Quest/diary/collection log icon sizing). */
	public static int combatReferenceSize(int iconMaxFit)
	{
		BufferedImage combatRaw = loadRawTaskIcon("Combat", null, null);
		BufferedImage combatScaled = combatRaw != null ? scaleToFitAllowUpscale(combatRaw, iconMaxFit, iconMaxFit) : null;
		return combatScaled != null ? Math.max(combatScaled.getWidth(), combatScaled.getHeight()) : iconMaxFit;
	}

	public static BufferedImage scaleTaskIcon(BufferedImage raw, String taskType, String displayName,
		int iconMaxFit, int refSize)
	{
		if (raw == null) return null;
		return IconResolver.isIconMatchCombatSize(taskType, displayName)
			? scaleToLargestDimension(raw, refSize)
			: scaleToFitAllowUpscale(raw, iconMaxFit, iconMaxFit);
	}

	public static BufferedImage scaleToFitAllowUpscale(BufferedImage src, int maxW, int maxH)
	{
		if (src == null || maxW <= 0 || maxH <= 0) return null;
		int w = src.getWidth();
		int h = src.getHeight();
		if (w <= 0 || h <= 0) return null;
		double scale = Math.min((double) maxW / w, (double) maxH / h);
		int nw = Math.max(1, (int) Math.round(w * scale));
		int nh = Math.max(1, (int) Math.round(h * scale));
		return (nw == w && nh == h) ? src : ImageUtil.resizeImage(src, nw, nh);
	}

	public static BufferedImage scaleToLargestDimension(BufferedImage src, int targetMaxDimension)
	{
		if (src == null || targetMaxDimension <= 0) return null;
		int w = src.getWidth();
		int h = src.getHeight();
		if (w <= 0 || h <= 0) return null;
		int maxDim = Math.max(w, h);
		if (maxDim <= 0) return null;
		double scale = (double) targetMaxDimension / maxDim;
		int nw = Math.max(1, (int) Math.round(w * scale));
		int nh = Math.max(1, (int) Math.round(h * scale));
		return (nw == w && nh == h) ? src : ImageUtil.resizeImage(src, nw, nh);
	}
}

package com.gridscape;

import java.io.InputStream;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.VarPlayer;
import net.runelite.client.audio.AudioPlayer;

/**
 * Plays GridScape UI sound effects from classpath resources under /soundeffects/.
 * Gain is in dB; 0f = normal volume. Use {@link #play(AudioPlayer, String)} or
 * {@link #play(AudioPlayer, String, Client)} with one of the public path constants.
 * When a {@link Client} is provided, volume follows the game's <b>Sound effects</b> slider
 * via {@link VarPlayer#SOUND_EFFECT_VOLUME} (same scale as {@link net.runelite.api.SoundEffectVolume}).
 */
@Slf4j
public final class GridScapeSounds
{
	private static final String PREFIX = "/soundeffects/";

	/** Played when the player tries to interact with a locked area or action. */
	public static final String LOCKED = PREFIX + "Locked.wav";
	/** Played when an action is invalid (e.g. not enough points to unlock). */
	public static final String WRONG = PREFIX + "Wrong_sound_effect.wav.ogg";
	/** Played on general button/clicks (dialogs, menus, etc.). */
	public static final String BUTTON_PRESS = PREFIX + "button_press.wav";
	public static final String EQUIP_FUN = PREFIX + "Equip_fun.wav";
	public static final String COINS_JINGLE = PREFIX + "Coins_jingle_(4).wav.ogg";
	/** Played when a task is auto-completed (e.g. collection log style). */
	public static final String TASK_COMPLETE = PREFIX + "Task_complete.wav";

	private static final float GAIN_DB_FULL = 0f;
	/** Gain when volume is 0 (mute). */
	private static final float GAIN_DB_MUTED = -80f;

	/**
	 * Converts the game volume (0 = mute; typical sound-effect steps up to 127; music may use up to 255) to dB gain.
	 */
	public static float volumeToGainDb(int volume0to255)
	{
		if (volume0to255 <= 0) return GAIN_DB_MUTED;
		if (volume0to255 >= 255) return GAIN_DB_FULL;
		// Logarithmic scale: 20 * log10((v+1)/256)
		double linear = (volume0to255 + 1) / 256.0;
		return (float) (20.0 * Math.log10(linear));
	}

	/**
	 * Plays a sound from a classpath resource path. Safe to call with null player or path (no-op).
	 * Logs at debug if the resource is missing or playback fails.
	 *
	 * @param player       RuneLite audio player (may be null)
	 * @param resourcePath classpath path (e.g. {@link #LOCKED}, or any path under /soundeffects/)
	 */
	public static void play(AudioPlayer player, String resourcePath)
	{
		play(player, resourcePath, null);
	}

	/**
	 * Plays a sound scaled by the game's <b>Sound effects</b> volume (Audio Settings in the client).
	 * Safe to call with null player, path, or client.
	 *
	 * @param player       RuneLite audio player (may be null)
	 * @param resourcePath classpath path (e.g. {@link #LOCKED})
	 * @param client       game client for volume (may be null; then full volume is used)
	 */
	public static void play(AudioPlayer player, String resourcePath, Client client)
	{
		if (player == null || resourcePath == null) return;
		float gain = GAIN_DB_FULL;
		if (client != null)
		{
			int vol = client.getVarpValue(VarPlayer.SOUND_EFFECT_VOLUME);
			gain = volumeToGainDb(vol);
			if (gain <= GAIN_DB_MUTED + 1f)
			{
				return; // Muted
			}
		}
		try (InputStream in = GridScapeSounds.class.getResourceAsStream(resourcePath))
		{
			if (in != null)
				player.play(in, gain);
		}
		catch (Exception e)
		{
			log.debug("GridScape sound failed {}: {}", resourcePath, e.getMessage());
		}
	}
}

