package com.gridscape.grid;

import java.util.ArrayList;
import java.util.List;

/** Spiral ring positions matching TaskGridService order. */
public final class Spiral
{
	private Spiral() {}

	public static List<int[]> ring(int tier)
	{
		if (tier < 1)
			return new ArrayList<>();
		List<int[]> out = new ArrayList<>(8 * tier);
		for (int c = 1 - tier; c <= tier; c++)
			out.add(new int[]{ tier, c });
		for (int r = tier - 1; r >= -tier; r--)
			out.add(new int[]{ r, tier });
		for (int c = tier - 1; c >= -tier; c--)
			out.add(new int[]{ -tier, c });
		for (int r = -tier + 1; r <= tier; r++)
			out.add(new int[]{ r, -tier });
		return out;
	}
}

package com.gridscape.grid;

import java.util.Set;

/** Cardinal-neighbor reveal rules for task grids and world-unlock placement. */
public final class RevealLogic
{
	private RevealLogic() {}

	public static boolean revealedByClaimedPositions(int row, int col, Set<String> claimedNeighborPositions)
	{
		if (row == 0 && col == 0)
			return true;
		return claimedNeighborPositions != null && !claimedNeighborPositions.isEmpty();
	}

	public static boolean revealedByClaimedTaskIds(int row, int col, Set<String> claimedPositions)
	{
		if (row == 0 && col == 0)
			return true;
		if (claimedPositions == null || claimedPositions.isEmpty())
			return false;
		for (String n : GridPos.neighbors4(row, col))
		{
			if (claimedPositions.contains(n))
				return true;
		}
		return false;
	}
}

package com.gridscape.grid;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Grid position helpers: parse "row,col", Chebyshev distance, cardinal neighbors. */
public final class GridPos
{
	private GridPos() {}

	public static int[] parse(String pos)
	{
		if (pos == null) return null;
		String p = pos.trim();
		int comma = p.indexOf(',');
		if (comma <= 0 || comma >= p.length() - 1) return null;
		try
		{
			int r = Integer.parseInt(p.substring(0, comma).trim());
			int c = Integer.parseInt(p.substring(comma + 1).trim());
			return new int[]{ r, c };
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	public static String normalize(String pos)
	{
		int[] rc = parse(pos);
		return rc == null ? (pos == null ? "" : pos.trim()) : rc[0] + "," + rc[1];
	}

	public static List<String> neighbors4(String pos)
	{
		int[] rc = parse(pos);
		if (rc == null) return Collections.emptyList();
		return neighbors4(rc[0], rc[1]);
	}

	public static List<String> neighbors4(int row, int col)
	{
		List<String> out = new ArrayList<>(4);
		out.add((row + 1) + "," + col);
		out.add((row - 1) + "," + col);
		out.add(row + "," + (col + 1));
		out.add(row + "," + (col - 1));
		return out;
	}

	public static int chebyshevDist(int r1, int c1, int r2, int c2)
	{
		return Math.max(Math.abs(r1 - r2), Math.abs(c1 - c2));
	}

	/**
	 * Ring index for task grids centered at (0,0): {@code max(|row|,|col|)}. Center is 0; first ring of 8 cells is 1.
	 */
	public static int ringNumber(int row, int col)
	{
		return Math.max(Math.abs(row), Math.abs(col));
	}
}

