	void notifyCornersUpdated()
	{
		if (cornerUpdateCallback != null)
		{
			List<int[]> copy = new ArrayList<>(areaEditState.getEditingCorners());
			SwingUtilities.invokeLater(() -> cornerUpdateCallback.accept(copy));
		}
	}

	void addCornerAtSelectedTile()
	{
		if (!areaEditState.isEditingArea()) return;
		WorldPoint wp = getSelectedWorldPoint();
		if (wp == null) return;
		areaEditState.addCornerFromWorldPoint(wp);
		notifyCornersUpdated();
		client.addChatMessage(net.runelite.api.ChatMessageType.GAMEMESSAGE, "", "Added corner: " + wp.getX() + ", " + wp.getY(), null);
	}

	void setCornerAtSelectedTile()
	{
		if (!areaEditState.isEditingArea() || areaEditState.getMoveCornerIndex() < 0) return;
		WorldPoint wp = getSelectedWorldPoint();
		if (wp == null) return;
		int moveCornerIndex = areaEditState.getMoveCornerIndex();
		if (moveCornerIndex < areaEditState.getEditingCorners().size())
		{
			areaEditState.setCornerPosition(moveCornerIndex, wp);
			notifyCornersUpdated();
			client.addChatMessage(net.runelite.api.ChatMessageType.GAMEMESSAGE, "", "Moved corner #" + moveCornerIndex + " to " + wp.getX() + ", " + wp.getY(), null);
		}
		areaEditState.setMoveCornerIndex(-1);
	}

	int findCornerAt(int x, int y, int plane)
	{
		return areaEditState.findCornerAt(x, y, plane);
	}

	private WorldPoint getSelectedWorldPoint()
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null) return null;
		Tile tile = wv.getSelectedSceneTile();
		if (tile == null) return null;
		return tileToWorldPoint(client, tile, wv);
	}

	static WorldPoint tileToWorldPoint(Client client, Tile tile, WorldView wv)
	{
		if (tile == null || wv == null) return null;
		var local = tile.getLocalLocation();
		if (local == null) return null;
		if (client.isInInstancedRegion())
			return WorldPoint.fromLocalInstance(client, local);
		return WorldPoint.fromLocal(wv, local.getX(), local.getY(), wv.getPlane());
	}
}

package com.gridscape.area;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonDeserializationContext;
import com.google.gson.JsonDeserializer;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.google.gson.JsonSerializationContext;
import com.google.gson.JsonSerializer;
import com.gridscape.data.Area;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.config.ConfigManager;

/**
 * Loads areas from areas.json and custom areas from config. Merges them and provides
 * unlocked set, neighbors, and point-in-area checks.
 */
@Slf4j
@Singleton
public class AreaGraphService
{
	private static final String AREAS_RESOURCE = "areas.json";
	private static final String CONFIG_GROUP = com.gridscape.util.GridScapeConfigConstants.CONFIG_GROUP_CUSTOM_AREAS;
	private static final String KEY_CUSTOM_AREAS = "customAreas";
	private static final String KEY_REMOVED_AREAS = "removedAreas";

	/** Handles Area JSON: reads "polygon" (legacy) or "polygons", always writes "polygons". */
	private static class AreaPolygonsAdapter implements JsonDeserializer<Area>, JsonSerializer<Area>
	{
		@Override
		public Area deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) throws JsonParseException
		{
			JsonObject obj = json.getAsJsonObject();
			List<List<int[]>> polygons;
			if (obj.has("polygons"))
			{
				polygons = deserializePolygons(obj.get("polygons"), context);
			}
			else if (obj.has("polygon"))
			{
				List<int[]> single = deserializePoints(obj.get("polygon"), context);
				polygons = single != null && !single.isEmpty() ? Collections.singletonList(single) : new ArrayList<>();
			}
			else
			{
				polygons = new ArrayList<>();
			}
			if (polygons == null) polygons = new ArrayList<>();

			String id = obj.has("id") ? obj.get("id").getAsString() : "";
			String displayName = obj.has("displayName") ? obj.get("displayName").getAsString() : id;
			String description = obj.has("description") && !obj.get("description").isJsonNull() ? obj.get("description").getAsString() : null;
			List<List<int[]>> holes = null;
			if (obj.has("holes"))
			{
				holes = deserializePolygons(obj.get("holes"), context);
			}
			if (holes == null) holes = new ArrayList<>();
			List<Integer> includes = obj.has("includes") ? arrayToList(context.deserialize(obj.get("includes"), Integer[].class)) : null;
			List<String> neighbors = obj.has("neighbors") ? arrayToList(context.deserialize(obj.get("neighbors"), String[].class)) : null;
			int unlockCost = obj.has("unlockCost") ? obj.get("unlockCost").getAsInt() : 0;
			Integer pointsToComplete = obj.has("pointsToComplete") && !obj.get("pointsToComplete").isJsonNull() ? obj.get("pointsToComplete").getAsInt() : null;

			return Area.builder()
				.id(id)
				.displayName(displayName)
				.description(description)
				.polygons(polygons)
				.holes(holes)
				.includes(includes != null ? includes : Collections.emptyList())
				.neighbors(neighbors != null ? neighbors : Collections.emptyList())
				.unlockCost(unlockCost)
				.pointsToComplete(pointsToComplete)
				.build();
		}

		private static List<List<int[]>> deserializePolygons(JsonElement el, JsonDeserializationContext context)
		{
			if (el == null || !el.isJsonArray()) return new ArrayList<>();
			List<List<int[]>> polygons = new ArrayList<>();
			for (JsonElement polyEl : el.getAsJsonArray())
			{
				polygons.add(deserializePoints(polyEl, context));
			}
			return polygons;
		}

		private static List<int[]> deserializePoints(JsonElement el, JsonDeserializationContext context)
		{
			if (el == null || !el.isJsonArray()) return new ArrayList<>();
			List<int[]> points = new ArrayList<>();
			for (JsonElement pt : el.getAsJsonArray())
			{
				int[] point = context.deserialize(pt, int[].class);
				if (point != null) points.add(point);
			}
			return points;
		}

		private static <T> List<T> arrayToList(T[] arr)
		{
			return arr == null ? new ArrayList<>() : new ArrayList<>(Arrays.asList(arr));
		}

		@Override
		public JsonElement serialize(Area src, Type typeOfSrc, JsonSerializationContext context)
		{
			JsonObject obj = new JsonObject();
			obj.add("id", context.serialize(src.getId()));
			obj.add("displayName", context.serialize(src.getDisplayName()));
			if (src.getDescription() != null) obj.add("description", context.serialize(src.getDescription()));
			obj.add("polygons", context.serialize(src.getPolygons()));
			if (src.getHoles() != null && !src.getHoles().isEmpty()) obj.add("holes", context.serialize(src.getHoles()));
			obj.add("includes", context.serialize(src.getIncludes()));
			obj.add("neighbors", context.serialize(src.getNeighbors()));
			obj.addProperty("unlockCost", src.getUnlockCost());
			if (src.getPointsToComplete() != null) obj.addProperty("pointsToComplete", src.getPointsToComplete());
			return obj;
		}
	}

	private final ConfigManager configManager;
	private final Gson gson;
	private final Gson gsonPretty;

	private volatile List<Area> areas = new ArrayList<>();
	private final Set<String> unlockedAreaIds = new HashSet<>();

	/** Cache: "areaId|plane" -> tiles inside that area's polygons. Cleared when areas reload. */
	private final Map<String, Set<WorldPoint>> tilesInAreaCache = new ConcurrentHashMap<>();
	/** Cache: plane -> tiles inside any locked area. Cleared when unlocked set or areas change. */
	private final Map<Integer, Set<WorldPoint>> tilesInLockedAreasCache = new ConcurrentHashMap<>();

	@Inject
	public AreaGraphService(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson.newBuilder()
			.registerTypeAdapter(int[].class, new JsonDeserializer<int[]>()
			{
				@Override
				public int[] deserialize(JsonElement json, Type type, JsonDeserializationContext context) throws JsonParseException
				{
					JsonArray arr = json.getAsJsonArray();
					int[] result = new int[arr.size()];
					for (int i = 0; i < arr.size(); i++)
					{
						result[i] = arr.get(i).getAsInt();
					}
					return result;
				}
			})
			.registerTypeAdapter(Area.class, new AreaPolygonsAdapter())
			.create();
		this.gsonPretty = gson.newBuilder().setPrettyPrinting().create();
		reloadAreas();
	}

	/** Reload built-in areas from JSON and custom areas from config. Custom overrides built-in by id. */
	public void reloadAreas()
	{
		List<Area> builtIn = loadBuiltInAreas();
		Set<String> removed = loadRemovedAreaIds();
		List<Area> custom = loadCustomAreas();
		areas = new ArrayList<>(builtIn);
		areas.removeIf(a -> removed.contains(a.getId()));
		for (Area c : custom)
		{
			areas.removeIf(a -> a.getId().equals(c.getId()));
			areas.add(c);
		}
		tilesInAreaCache.clear();
		tilesInLockedAreasCache.clear();
		log.debug("Loaded {} areas ({} built-in, {} removed, {} custom)", areas.size(), builtIn.size(), removed.size(), custom.size());
	}

	private List<Area> loadBuiltInAreas()
	{
		try (InputStream is = getClass().getResourceAsStream("/" + AREAS_RESOURCE))
		{
			if (is == null)
			{
				log.warn("areas.json not found in resources");
				return new ArrayList<>();
			}
			Area[] arr = gson.fromJson(
				new InputStreamReader(is, StandardCharsets.UTF_8),
				Area[].class);
			return arr == null ? new ArrayList<>() : new ArrayList<>(Arrays.asList(arr));
		}
		catch (Exception e)
		{
			log.error("Failed to load areas.json", e);
			return new ArrayList<>();
		}
	}

	private List<Area> loadCustomAreas()
	{
		String raw = configManager.getConfiguration(CONFIG_GROUP, KEY_CUSTOM_AREAS);
		if (raw == null || raw.isEmpty()) return new ArrayList<>();
		try
		{
			Area[] arr = gson.fromJson(raw, Area[].class);
			return arr == null ? new ArrayList<>() : new ArrayList<>(Arrays.asList(arr));
		}
		catch (Exception e)
		{
			log.error("Failed to parse custom areas", e);
			return new ArrayList<>();
		}
	}

	private Set<String> loadRemovedAreaIds()
	{
		String raw = configManager.getConfiguration(CONFIG_GROUP, KEY_REMOVED_AREAS);
		if (raw == null || raw.isEmpty()) return new HashSet<>();
		try
		{
			String[] arr = gson.fromJson(raw, String[].class);
			return arr == null ? new HashSet<>() : new HashSet<>(Arrays.asList(arr));
		}
		catch (Exception e)
		{
			log.error("Failed to parse removed areas", e);
			return new HashSet<>();
		}
	}

	private void persistRemovedAreaIds(Set<String> ids)
	{
		String json = gson.toJson(new ArrayList<>(ids));
		configManager.setConfiguration(CONFIG_GROUP, KEY_REMOVED_AREAS, json);
	}

	/**
	 * Save or update a custom area. Computes includes from polygon region IDs.
	 * Merges with existing custom areas and persists.
	 */
	public void saveCustomArea(Area area)
	{
		Area withIncludes = Area.builder()
			.id(area.getId())
			.displayName(area.getDisplayName())
			.description(area.getDescription())
			.polygons(area.getPolygons())
			.holes(area.getHoles() != null ? area.getHoles() : Collections.emptyList())
			.includes(computeIncludesFromPolygon(area.getPolygon()))
			.neighbors(area.getNeighbors() != null ? area.getNeighbors() : Collections.emptyList())
			.unlockCost(area.getUnlockCost())
			.pointsToComplete(area.getPointsToComplete())
			.build();

		List<Area> custom = new ArrayList<>(loadCustomAreas());
		custom.removeIf(a -> a.getId().equals(withIncludes.getId()));
		custom.add(withIncludes);
		persistCustomAreas(custom);
		reloadAreas();
	}

	/**
	 * Remove an area from the list. Custom areas are removed from config.
	 * Built-in areas are added to the removed list (hidden but can be restored).
	 */
	public void removeArea(String areaId)
	{
		if (areaId == null) return;
		if (loadCustomAreas().stream().anyMatch(a -> a.getId().equals(areaId)))
		{
			List<Area> custom = new ArrayList<>(loadCustomAreas());
			custom.removeIf(a -> a.getId().equals(areaId));
			persistCustomAreas(custom);
		}
		else if (loadBuiltInAreas().stream().anyMatch(a -> a.getId().equals(areaId)))
		{
			Set<String> removed = new HashSet<>(loadRemovedAreaIds());
			removed.add(areaId);
			persistRemovedAreaIds(removed);
		}
		reloadAreas();
	}

	/** Restore a previously removed built-in area. */
	public void restoreArea(String areaId)
	{
		if (areaId == null) return;
		Set<String> removed = new HashSet<>(loadRemovedAreaIds());
		removed.remove(areaId);
		persistRemovedAreaIds(removed);
		reloadAreas();
	}

	/** True if the area was removed (built-in area hidden by user). */
	public boolean isRemovedArea(String areaId)
	{
		return loadRemovedAreaIds().contains(areaId);
	}

	/** Ids of removed built-in areas (for UI restore list). */
	public Set<String> getRemovedAreaIds()
	{
		return Collections.unmodifiableSet(loadRemovedAreaIds());
	}

	/** Export current areas (built-in minus removed, plus custom) as pretty-printed JSON. */
	public String exportAreasToJson()
	{
		return gsonPretty.toJson(areas);
	}

	/**
	 * Parse and validate JSON, then replace custom areas with the imported list.
	 * Validates: root is array, each area has id, polygon (3+ points, each [x,y,plane]), and valid structure.
	 * @return the number of areas imported
	 * @throws IllegalArgumentException with a descriptive message if JSON is invalid or validation fails
	 */
	public int importCustomAreasFromJson(String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			throw new IllegalArgumentException("JSON is empty.");
		}
		List<Area> list;
		try
		{
			Area[] arr = gson.fromJson(json, Area[].class);
			list = arr == null ? null : new ArrayList<>(Arrays.asList(arr));
		}
		catch (JsonParseException e)
		{
			throw new IllegalArgumentException("Invalid JSON: " + e.getMessage());
		}
		if (list == null)
		{
			throw new IllegalArgumentException("JSON root must be an array of area objects.");
		}
		Set<String> seenIds = new HashSet<>();
		for (int i = 0; i < list.size(); i++)
		{
			Area a = list.get(i);
			if (a == null)
			{
				throw new IllegalArgumentException("Area at index " + i + " is null.");
			}
			if (a.getId() == null || a.getId().trim().isEmpty())
			{
				throw new IllegalArgumentException("Area at index " + i + " has missing or empty \"id\".");
			}
			if (seenIds.contains(a.getId()))
			{
				throw new IllegalArgumentException("Duplicate area id: \"" + a.getId() + "\".");
			}
			seenIds.add(a.getId());
			if (a.getPolygon() == null)
			{
				throw new IllegalArgumentException("Area \"" + a.getId() + "\" has missing \"polygon\".");
			}
			if (a.getPolygon().size() < 3)
			{
				throw new IllegalArgumentException("Area \"" + a.getId() + "\" must have at least 3 polygon corners (has " + a.getPolygon().size() + ").");
			}
			for (int j = 0; j < a.getPolygon().size(); j++)
			{
				int[] pt = a.getPolygon().get(j);
				if (pt == null || pt.length < 3)
				{
					throw new IllegalArgumentException("Area \"" + a.getId() + "\" polygon point " + j + " must be [x, y, plane] (3 numbers).");
				}
				int plane = pt[2];
				if (plane < 0 || plane > 3)
				{
					throw new IllegalArgumentException("Area \"" + a.getId() + "\" polygon point " + j + " has invalid plane " + plane + " (must be 0-3).");
				}
			}
			if (a.getUnlockCost() < 0)
			{
				throw new IllegalArgumentException("Area \"" + a.getId() + "\" has invalid unlockCost (must be >= 0).");
			}
			if (a.getPointsToComplete() != null && a.getPointsToComplete() < 0)
			{
				throw new IllegalArgumentException("Area \"" + a.getId() + "\" has invalid pointsToComplete (must be >= 0).");
			}
			if (a.getNeighbors() != null)
			{
				for (String n : a.getNeighbors())
				{
					if (n == null || n.trim().isEmpty())
					{
						throw new IllegalArgumentException("Area \"" + a.getId() + "\" has null or empty neighbor entry.");
					}
				}
			}
		}
		List<Area> withIncludes = new ArrayList<>();
		for (Area a : list)
		{
			Area normalized = Area.builder()
				.id(a.getId())
				.displayName(a.getDisplayName() != null ? a.getDisplayName() : a.getId())
				.description(a.getDescription())
				.polygons(a.getPolygons())
				.holes(a.getHoles() != null ? a.getHoles() : Collections.emptyList())
				.includes(a.getIncludes() != null && !a.getIncludes().isEmpty() ? a.getIncludes() : computeIncludesFromPolygon(a.getPolygon()))
				.neighbors(a.getNeighbors() != null ? a.getNeighbors() : Collections.emptyList())
				.unlockCost(a.getUnlockCost())
				.pointsToComplete(a.getPointsToComplete())
				.build();
			withIncludes.add(normalized);
		}
		persistCustomAreas(withIncludes);
		reloadAreas();
		log.info("Imported {} areas from JSON.", withIncludes.size());
		return withIncludes.size();
	}

	/** Check if an area is a built-in area (from areas.json). */
	public boolean isBuiltInArea(String areaId)
	{
		return loadBuiltInAreas().stream().anyMatch(a -> a.getId().equals(areaId));
	}

	/** Get a built-in area by id (for display name of removed areas). */
	public Area getBuiltInArea(String areaId)
	{
		return loadBuiltInAreas().stream()
			.filter(a -> a.getId().equals(areaId))
			.findFirst()
			.orElse(null);
	}

	private void persistCustomAreas(List<Area> custom)
	{
		String json = gson.toJson(custom);
		configManager.setConfiguration(CONFIG_GROUP, KEY_CUSTOM_AREAS, json);
	}

	/**
	 * Compute all region IDs covered by the polygon (for includes).
	 * Samples the polygon bounding box to ensure full coverage, not just vertices.
	 */
	private List<Integer> computeIncludesFromPolygon(List<int[]> polygon)
	{
		if (polygon == null || polygon.isEmpty()) return Collections.emptyList();
		Set<Integer> ids = new HashSet<>();
		int minX = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE;
		int minY = Integer.MAX_VALUE, maxY = Integer.MIN_VALUE;
		for (int[] v : polygon)
		{
			int x = v[0], y = v[1];
			minX = Math.min(minX, x);
			maxX = Math.max(maxX, x);
			minY = Math.min(minY, y);
			maxY = Math.max(maxY, y);
		}
		// Add all regions in the bounding box; sample at region centers (every 64 tiles)
		for (int rx = (minX >> 6) << 6; rx <= maxX; rx += 64)
		{
			for (int ry = (minY >> 6) << 6; ry <= maxY; ry += 64)
			{
				int cx = rx + 32;
				int cy = ry + 32;
				if (pointInPolygonRaw(cx, cy, polygon))
				{
					int regionId = (cx >> 6) << 8 | (cy >> 6);
					ids.add(regionId);
				}
			}
		}
		// Also add vertex regions (for small polygons that might miss the sampling)
		for (int[] v : polygon)
		{
			int regionId = (v[0] >> 6) << 8 | (v[1] >> 6);
			ids.add(regionId);
		}
		return new ArrayList<>(ids);
	}

	private boolean pointInPolygonRaw(int x, int y, List<int[]> polygon)
	{
		if (polygon == null || polygon.size() < 3) return false;
		int n = polygon.size();
		boolean inside = false;
		for (int i = 0, j = n - 1; i < n; j = i++)
		{
			int[] vi = polygon.get(i);
			int[] vj = polygon.get(j);
			int xi = vi[0], yi = vi[1];
			int xj = vj[0], yj = vj[1];
			if (yi == yj) continue;
			if (((yi > y) != (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi))
			{
				inside = !inside;
			}
		}
		return inside;
	}

	/**
	 * True if polygon inner is entirely inside polygon outer (every vertex of inner is inside outer).
	 * Both must have 3+ vertices and the same plane.
	 */
	public boolean isPolygonInsidePolygon(List<int[]> outer, List<int[]> inner)
	{
		if (outer == null || outer.size() < 3 || inner == null || inner.size() < 3) return false;
		int outerPlane = outer.get(0).length >= 3 ? outer.get(0)[2] : 0;
		for (int[] v : inner)
		{
			if (v.length < 2) return false;
			if (v.length >= 3 && v[2] != outerPlane) return false;
			if (!pointInPolygonRaw(v[0], v[1], outer)) return false;
		}
		return true;
	}

	public void setUnlockedAreaIds(Set<String> ids)
	{
		unlockedAreaIds.clear();
		if (ids != null)
		{
			unlockedAreaIds.addAll(ids);
		}
		tilesInLockedAreasCache.clear();
	}

	public void addUnlocked(String areaId)
	{
		unlockedAreaIds.add(areaId);
		tilesInLockedAreasCache.clear();
	}

	public Set<String> getUnlockedAreaIds()
	{
		return Collections.unmodifiableSet(unlockedAreaIds);
	}

	/** True if the point is inside any area's polygon. */
	public boolean isWorldPointInAnyArea(WorldPoint worldPoint)
	{
		return getAreaAt(worldPoint) != null;
	}

	/** Returns the first area that has any polygon containing the given world point (surface plane), or null. Points inside any hole are excluded. */
	public Area getAreaAt(WorldPoint worldPoint)
	{
		for (Area a : areas)
		{
			if (!isWorldPointInArea(worldPoint, a)) continue;
			return a;
		}
		return null;
	}

	/** True if the world point is inside the area (in some polygon and not in any hole). */
	public boolean isWorldPointInArea(WorldPoint worldPoint, Area area)
	{
		boolean inPoly = false;
		if (area.getPolygons() != null)
		{
			for (List<int[]> poly : area.getPolygons())
			{
				if (poly != null && poly.size() >= 3 && pointInPolygon(worldPoint, poly))
				{
					inPoly = true;
					break;
				}
			}
		}
		if (!inPoly) return false;
		if (area.getHoles() != null)
		{
			for (List<int[]> hole : area.getHoles())
			{
				if (hole != null && hole.size() >= 3 && pointInPolygon(worldPoint, hole))
					return false;
			}
		}
		return true;
	}

	public boolean isWorldPointUnlocked(WorldPoint worldPoint)
	{
		int regionId = (worldPoint.getX() >> 6) << 8 | (worldPoint.getY() >> 6);
		for (String areaId : unlockedAreaIds)
		{
			Area area = getArea(areaId);
			if (area == null) continue;
			if (area.getIncludes() != null && area.getIncludes().contains(regionId))
			{
				return true;
			}
			if (isWorldPointInArea(worldPoint, area))
				return true;
		}
		return false;
	}

	private boolean pointInPolygon(WorldPoint p, List<int[]> polygon)
	{
		if (polygon == null || polygon.size() < 3) return false;
		int x = p.getX(), y = p.getY(), plane = p.getPlane();
		int n = polygon.size();
		// Plane must match: polygon vertices use [x, y, plane]; if present, enforce
		int polyPlane = polygon.get(0).length >= 3 ? polygon.get(0)[2] : 0;
		if (plane != polyPlane) return false;

		boolean inside = false;
		for (int i = 0, j = n - 1; i < n; j = i++)
		{
			int[] vi = polygon.get(i);
			int[] vj = polygon.get(j);
			int xi = vi[0], yi = vi[1];
			int xj = vj[0], yj = vj[1];
			if (yi == yj) continue; // skip horizontal edge to avoid division by zero
			if (((yi > y) != (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi))
			{
				inside = !inside;
			}
		}
		return inside;
	}

	/**
	 * Returns all world tiles (origin x,y) that lie inside the area's polygons on the given plane.
	 * Cached per (areaId, plane); cache cleared when areas reload.
	 */
	public Set<WorldPoint> getTilesInArea(Area area, int plane)
	{
		String key = area.getId() + "|" + plane;
		Set<WorldPoint> cached = tilesInAreaCache.get(key);
		if (cached != null)
		{
			return cached;
		}
		Set<WorldPoint> out = new HashSet<>();
		List<List<int[]>> polygons = area.getPolygons();
		if (polygons != null)
		{
			for (List<int[]> polygon : polygons)
			{
				if (polygon == null || polygon.size() < 3) continue;
				int polyPlane = polygon.get(0).length >= 3 ? polygon.get(0)[2] : 0;
				if (polyPlane != plane) continue;
				int minX = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE;
				int minY = Integer.MAX_VALUE, maxY = Integer.MIN_VALUE;
				for (int[] v : polygon)
				{
					if (v.length < 2) continue;
					int vx = v[0], vy = v[1];
					minX = Math.min(minX, vx);
					maxX = Math.max(maxX, vx);
					minY = Math.min(minY, vy);
					maxY = Math.max(maxY, vy);
				}
				for (int x = minX; x <= maxX; x++)
				{
					for (int y = minY; y <= maxY; y++)
					{
						if (pointInPolygonRaw(x, y, polygon))
						{
							out.add(new WorldPoint(x, y, plane));
						}
					}
				}
			}
		}
		// Remove tiles that fall inside any hole
		List<List<int[]>> holes = area.getHoles();
		if (holes != null && !holes.isEmpty())
		{
			for (List<int[]> hole : holes)
			{
				if (hole == null || hole.size() < 3) continue;
				int holePlane = hole.get(0).length >= 3 ? hole.get(0)[2] : 0;
				if (holePlane != plane) continue;
				for (java.util.Iterator<WorldPoint> it = out.iterator(); it.hasNext(); )
				{
					WorldPoint wp = it.next();
					if (pointInPolygonRaw(wp.getX(), wp.getY(), hole))
						it.remove();
				}
			}
		}
		tilesInAreaCache.put(key, out);
		return out;
	}

	/**
	 * Returns all tiles on the given plane that lie inside any locked area's polygons (areas not in unlocked set).
	 * Cached per plane; cache cleared when unlocked set or areas change.
	 */
	public Set<WorldPoint> getTilesInLockedAreas(int plane)
	{
		Set<WorldPoint> cached = tilesInLockedAreasCache.get(plane);
		if (cached != null)
		{
			return cached;
		}
		Set<WorldPoint> out = new HashSet<>();
		Set<String> unlocked = getUnlockedAreaIds();
		for (Area area : areas)
		{
			if (unlocked.contains(area.getId())) continue;
			out.addAll(getTilesInArea(area, plane));
		}
		tilesInLockedAreasCache.put(plane, out);
		return out;
	}

	/**
	 * Neighbors of unlocked areas that are still locked. In points-to-complete mode pass completedAreaIds
	 * to only return neighbors that border at least one completed area.
	 */
	public List<Area> getUnlockableNeighbors(Set<String> completedAreaIds)
	{
		Set<String> neighborIds = new HashSet<>();
		Set<String> sourceAreas = (completedAreaIds != null && !completedAreaIds.isEmpty())
			? new HashSet<>(completedAreaIds)
			: unlockedAreaIds;
		for (String areaId : sourceAreas)
		{
			if (!unlockedAreaIds.contains(areaId)) continue;
			Area area = getArea(areaId);
			if (area != null && area.getNeighbors() != null)
			{
				for (String n : area.getNeighbors())
				{
					if (!unlockedAreaIds.contains(n))
					{
						neighborIds.add(n);
					}
				}
			}
		}
		return neighborIds.stream()
			.map(this::getArea)
			.filter(a -> a != null)
			.collect(Collectors.toList());
	}

	/** All locked neighbors of any unlocked area (point-buy mode). */
	public List<Area> getUnlockableNeighbors()
	{
		return getUnlockableNeighbors(null);
	}

	public int getCost(String areaId)
	{
		Area area = getArea(areaId);
		return area != null ? area.getUnlockCost() : 0;
	}

	/** Points to earn in this area to complete it (points-to-complete mode). If area has no pointsToComplete set, returns unlockCost. */
	public int getPointsToComplete(String areaId)
	{
		Area area = getArea(areaId);
		if (area == null) return 0;
		return area.getPointsToComplete() != null ? area.getPointsToComplete() : area.getUnlockCost();
	}

	public Area getArea(String areaId)
	{
		for (Area a : areas)
		{
			if (a.getId().equals(areaId)) return a;
		}
		return null;
	}

	public List<Area> getAreas()
	{
		return Collections.unmodifiableList(areas);
	}

	/**
	 * Returns boundary edges (corner-to-corner) that separate locked from unlocked areas.
	 * Edges between two unlocked areas are excluded. Each edge is {x1,y1,plane,x2,y2} (plane shared).
	 */
	public List<int[]> getBoundaryEdges(int plane)
	{
		Set<String> unlocked = getUnlockedAreaIds();
		Map<String, Set<String>> edgeToAreas = new HashMap<>();

		for (Area area : areas)
		{
			List<int[]> poly = area.getPolygon();
			if (poly == null || poly.size() < 3) continue;

			int n = poly.size();
			for (int i = 0; i < n; i++)
			{
				int[] v1 = poly.get(i);
				int[] v2 = poly.get((i + 1) % n);
				if (v1.length < 3 || v2.length < 3) continue;
				if (v1[2] != plane || v2[2] != plane) continue;

				String key = edgeKey(v1[0], v1[1], v2[0], v2[1]);
				edgeToAreas.computeIfAbsent(key, k -> new HashSet<>()).add(area.getId());
			}
		}

		Set<String> added = new HashSet<>();
		List<int[]> result = new ArrayList<>();
		for (Area area : areas)
		{
			List<int[]> poly = area.getPolygon();
			if (poly == null || poly.size() < 3) continue;

			int n = poly.size();
			for (int i = 0; i < n; i++)
			{
				int[] v1 = poly.get(i);
				int[] v2 = poly.get((i + 1) % n);
				if (v1.length < 3 || v2.length < 3) continue;
				if (v1[2] != plane || v2[2] != plane) continue;

				String key = edgeKey(v1[0], v1[1], v2[0], v2[1]);
				if (added.contains(key)) continue;

				Set<String> areaIds = edgeToAreas.get(key);
				if (areaIds == null) continue;

				// Skip if both neighboring areas are unlocked
				boolean allUnlocked = areaIds.stream().allMatch(unlocked::contains);
				if (allUnlocked) continue;

				// Draw: boundary between locked and unlocked, or external edge of locked area
				added.add(key);
				result.add(new int[]{v1[0], v1[1], v1[2], v2[0], v2[1]});
			}
		}
		return result;
	}

	/**
	 * Returns edge keys for boundaries between locked and unlocked areas only.
	 * These edges must not be extended to the viewport (would render over unlocked).
	 * Excludes edges that border only locked areas or external edges.
	 */
	public Set<String> getBoundaryEdgeKeys(int plane)
	{
		Set<String> unlocked = getUnlockedAreaIds();
		Map<String, Set<String>> edgeToAreas = new HashMap<>();

		for (Area area : areas)
		{
			List<int[]> poly = area.getPolygon();
			if (poly == null || poly.size() < 3) continue;

			int n = poly.size();
			for (int i = 0; i < n; i++)
			{
				int[] v1 = poly.get(i);
				int[] v2 = poly.get((i + 1) % n);
				if (v1.length < 3 || v2.length < 3) continue;
				if (v1[2] != plane || v2[2] != plane) continue;

				String key = edgeKey(v1[0], v1[1], v2[0], v2[1]);
				edgeToAreas.computeIfAbsent(key, k -> new HashSet<>()).add(area.getId());
			}
		}

		Set<String> result = new HashSet<>();
		for (Map.Entry<String, Set<String>> e : edgeToAreas.entrySet())
		{
			Set<String> areaIds = e.getValue();
			boolean hasLocked = areaIds.stream().anyMatch(id -> !unlocked.contains(id));
			boolean hasUnlocked = areaIds.stream().anyMatch(unlocked::contains);
			if (hasLocked && hasUnlocked)
			{
				result.add(e.getKey());
			}
		}
		return result;
	}

	private static String edgeKey(int x1, int y1, int x2, int y2)
	{
		if (x1 < x2 || (x1 == x2 && y1 <= y2))
		{
			return x1 + "," + y1 + "," + x2 + "," + y2;
		}
		return x2 + "," + y2 + "," + x1 + "," + y1;
	}
}

package com.gridscape.lock;

import com.gridscape.GridScapeConfig;
import com.gridscape.area.AreaGraphService;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * When the locked region overlay is active, blocks any click on a tile where the overlay
 * is drawn. Uses the same logic as the overlay: the tile must be inside a locked area's
 * polygon (getTilesInLockedAreas). If the click is inside a locked polygon, intercept and
 * block; otherwise do nothing.
 */
@Slf4j
public class LockEnforcer
{
	private final Client client;
	private final GridScapeConfig config;
	private final AreaGraphService areaGraphService;

	/** Tile under the cursor, updated every tick so we have it when menu events fire. */
	private WorldPoint cursorTileWorldPoint = null;
	private boolean inLockedZone = false;

	@Inject
	public LockEnforcer(Client client, GridScapeConfig config, AreaGraphService areaGraphService)
	{
		this.client = client;
		this.config = config;
		this.areaGraphService = areaGraphService;
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		if (client.getLocalPlayer() == null)
		{
			cursorTileWorldPoint = null;
			return;
		}
		// Capture the tile under the cursor every tick so we have it when MenuOpened/MenuOptionClicked fire
		cursorTileWorldPoint = getSelectedTileWorldPoint();

		LocalPoint local = client.getLocalPlayer().getLocalLocation();
		if (local == null) return;
		WorldPoint world;
		if (client.isInInstancedRegion())
			world = WorldPoint.fromLocalInstance(client, local);
		else
			world = WorldPoint.fromLocal(client, local);
		// Same as overlay: player is in locked zone if their tile is in the locked-tiles set (polygon-based)
		inLockedZone = world != null && areaGraphService.getTilesInLockedAreas(world.getPlane()).contains(world);
	}

	/**
	 * If the overlay is active and the click was on a locked tile, remove all world-targeting
	 * menu entries so the user cannot choose any of them. Skipped when strict lock enforcement is off.
	 */
	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (!config.renderLockedOverlay() || !config.strictLockEnforcement()) return;
		if (client.getLocalPlayer() == null) return;

		WorldPoint clickedTile = getClickedTileWorldPoint();
		if (clickedTile == null) return;
		// Same logic as overlay: block only if this tile is in the locked polygon set (not includes-based)
		if (!areaGraphService.getTilesInLockedAreas(clickedTile.getPlane()).contains(clickedTile)) return;

		// Click was on a locked overlay tile: remove every entry that targets the world (walk, object, npc, etc.)
		MenuEntry[] entries = client.getMenuEntries();
		if (entries == null || entries.length == 0) return;

		List<MenuEntry> keep = new ArrayList<>(entries.length);
		for (MenuEntry entry : entries)
		{
			if (entry.getWidget() != null)
			{
				keep.add(entry);
				continue;
			}
			if (!isWorldTargetingAction(entry.getType()))
				keep.add(entry);
		}
		if (keep.size() < entries.length)
			client.setMenuEntries(keep.toArray(new MenuEntry[0]));
	}

	/**
	 * If the overlay is active and the click was on a locked tile, consume the event so
	 * the game never receives the action (no path, no interact). Skipped when strict lock enforcement is off.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!config.renderLockedOverlay() || !config.strictLockEnforcement()) return;
		if (client.getLocalPlayer() == null) return;

		String option = Text.removeFormattingTags(event.getMenuOption());
		if ("Cancel".equals(option)) return;
		// Clicks on widgets (inventory, spellbook, etc.) are not blocked by the overlay
		if (event.getMenuEntry().getWidget() != null) return;
		if (!isWorldTargetingAction(event.getMenuEntry().getType())) return;

		WorldPoint clickedTile = getClickedTileWorldPoint();
		if (clickedTile == null) return;
		// Same logic as overlay: block only if this tile is inside a locked polygon
		if (!areaGraphService.getTilesInLockedAreas(clickedTile.getPlane()).contains(clickedTile)) return;

		// Click was on a locked overlay tile: block it
		event.consume();
		client.addChatMessage(net.runelite.api.ChatMessageType.GAMEMESSAGE, "", "Locked area.", null);
	}

	public boolean isInLockedZone()
	{
		return inLockedZone;
	}

	/** The tile under the cursor (where the user clicked). Uses last tick's value so it's set when menu events run. */
	private WorldPoint getClickedTileWorldPoint()
	{
		// Prefer current selected tile in case it's still set
		WorldPoint current = getSelectedTileWorldPoint();
		if (current != null) return current;
		return cursorTileWorldPoint;
	}

	/** Current selected scene tile as world point (tile under cursor), from main view or minimap. */
	private WorldPoint getSelectedTileWorldPoint()
	{
		Tile tile = findSelectedTileInAnyWorldView();
		if (tile == null) return null;
		LocalPoint local = tile.getLocalLocation();
		if (local == null) return null;
		if (client.isInInstancedRegion())
			return WorldPoint.fromLocalInstance(client, local);
		return WorldPoint.fromLocal(client, local);
	}

	private static boolean isWorldTargetingAction(MenuAction action)
	{
		switch (action)
		{
			case WALK:
			case SET_HEADING:
			case GAME_OBJECT_FIRST_OPTION:
			case GAME_OBJECT_SECOND_OPTION:
			case GAME_OBJECT_THIRD_OPTION:
			case GAME_OBJECT_FOURTH_OPTION:
			case GAME_OBJECT_FIFTH_OPTION:
			case NPC_FIRST_OPTION:
			case NPC_SECOND_OPTION:
			case NPC_THIRD_OPTION:
			case NPC_FOURTH_OPTION:
			case NPC_FIFTH_OPTION:
			case GROUND_ITEM_FIRST_OPTION:
			case GROUND_ITEM_SECOND_OPTION:
			case GROUND_ITEM_THIRD_OPTION:
			case GROUND_ITEM_FOURTH_OPTION:
			case GROUND_ITEM_FIFTH_OPTION:
			case PLAYER_FIRST_OPTION:
			case PLAYER_SECOND_OPTION:
			case PLAYER_THIRD_OPTION:
			case PLAYER_FOURTH_OPTION:
			case PLAYER_FIFTH_OPTION:
			case PLAYER_SIXTH_OPTION:
			case PLAYER_SEVENTH_OPTION:
			case PLAYER_EIGHTH_OPTION:
			case WIDGET_TARGET_ON_GAME_OBJECT:
			case WIDGET_TARGET_ON_GROUND_ITEM:
			case WIDGET_TARGET_ON_NPC:
			case WIDGET_TARGET_ON_PLAYER:
			case WORLD_ENTITY_FIRST_OPTION:
			case WORLD_ENTITY_SECOND_OPTION:
			case WORLD_ENTITY_THIRD_OPTION:
			case WORLD_ENTITY_FOURTH_OPTION:
			case WORLD_ENTITY_FIFTH_OPTION:
			case EXAMINE_OBJECT:
			case EXAMINE_NPC:
			case EXAMINE_ITEM_GROUND:
			case EXAMINE_WORLD_ENTITY:
				return true;
			default:
				return false;
		}
	}

	private Tile findSelectedTileInAnyWorldView()
	{
		WorldView top = client.getTopLevelWorldView();
		if (top == null) return null;
		Tile t = top.getSelectedSceneTile();
		if (t != null) return t;
		try
		{
			for (WorldView child : top.worldViews())
			{
				t = child.getSelectedSceneTile();
				if (t != null) return t;
			}
		}
		catch (Exception ignored) { }
		return null;
	}
}

package com.gridscape.points;

import com.gridscape.GridScapeConfig;
import com.gridscape.area.AreaGraphService;
import com.gridscape.data.AreaStatus;
import com.gridscape.task.TaskGridService;
import java.util.Collections;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Provider;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Tracks points earned per area and which areas are "complete" (earned enough points in that area).
 * Used when unlock mode is POINTS_TO_COMPLETE: complete an area by earning points there, then you can unlock the next.
 */
@Slf4j
@Singleton
public class AreaCompletionService
{
	private static final String CONFIG_GROUP = com.gridscape.util.GridScapeConfigConstants.STATE_GROUP;
	private static final String KEY_POINTS_PER_AREA = "pointsEarnedPerArea";
	private static final String KEY_COMPLETED_AREAS = "completedAreas";

	private final ConfigManager configManager;
	private final AreaGraphService areaGraphService;
	private final PointsService pointsService;
	private final GridScapeConfig config;

	private final Map<String, Integer> pointsEarnedInArea = new ConcurrentHashMap<>();
	private final Set<String> completedAreaIds = new HashSet<>();
	private final Provider<TaskGridService> taskGridServiceProvider;

	@Inject
	public AreaCompletionService(ConfigManager configManager, AreaGraphService areaGraphService, PointsService pointsService, GridScapeConfig config,
		Provider<TaskGridService> taskGridServiceProvider)
	{
		this.configManager = configManager;
		this.areaGraphService = areaGraphService;
		this.pointsService = pointsService;
		this.config = config;
		this.taskGridServiceProvider = taskGridServiceProvider;
	}

	/**
	 * Loads points-per-area and completed-areas from config. Clears in-memory maps first, then
	 * parses KEY_POINTS_PER_AREA (format "areaId:points,areaId:points,...") and KEY_COMPLETED_AREAS
	 * (comma-separated area IDs). Recomputes completed set from points in case the area's
	 * points-to-complete threshold changed, then persists the completed list.
	 */
	public void loadFromConfig()
	{
		pointsEarnedInArea.clear();
		String raw = configManager.getConfiguration(CONFIG_GROUP, KEY_POINTS_PER_AREA);
		if (raw != null && !raw.isEmpty())
		{
			for (String part : raw.split(","))
			{
				String[] kv = part.split(":", 2);
				if (kv.length == 2)
				{
					try
					{
						String areaId = kv[0].trim();
						int points = Integer.parseInt(kv[1].trim());
						if (!areaId.isEmpty() && points > 0)
							pointsEarnedInArea.put(areaId, points);
					}
					catch (NumberFormatException ignored) { }
				}
			}
		}

		completedAreaIds.clear();
		completedAreaIds.addAll(com.gridscape.util.ConfigParsing.parseCommaSeparatedSet(configManager.getConfiguration(CONFIG_GROUP, KEY_COMPLETED_AREAS)));
		// Recompute completed from points (in case area pointsToComplete threshold changed in config)
		for (String areaId : pointsEarnedInArea.keySet())
		{
			if (getPointsEarnedInArea(areaId) >= getPointsToComplete(areaId))
				completedAreaIds.add(areaId);
		}
		persistCompleted();
	}

	/** Points earned in this area (from completing tasks there). */
	public int getPointsEarnedInArea(String areaId)
	{
		return pointsEarnedInArea.getOrDefault(areaId, 0);
	}

	/** Points required to "complete" this area (uses area's pointsToComplete, or unlockCost if not set). */
	public int getPointsToComplete(String areaId)
	{
		return areaGraphService.getPointsToComplete(areaId);
	}

	/** True if this area has been completed (earned enough points in it). */
	public boolean isComplete(String areaId)
	{
		return completedAreaIds.contains(areaId);
	}

	/** Set of area IDs that are complete. Unmodifiable. */
	public Set<String> getCompletedAreaIds()
	{
		return Collections.unmodifiableSet(completedAreaIds);
	}

	/**
	 * Set of area IDs that count as "complete" for gating the next unlock.
	 * Points-to-complete mode: areas that have earned at least their points-to-complete threshold.
	 * Point-buy mode: unlocked areas that have every task completed.
	 */
	public Set<String> getEffectiveCompletedAreaIds()
	{
		if (config.unlockMode() == GridScapeConfig.UnlockMode.POINT_BUY)
		{
			Set<String> out = new HashSet<>();
			TaskGridService taskGrid = taskGridServiceProvider.get();
			for (String areaId : areaGraphService.getUnlockedAreaIds())
			{
				if (taskGrid.isAreaFullyCompleted(areaId)) out.add(areaId);
			}
			return out;
		}
		return Collections.unmodifiableSet(completedAreaIds);
	}

	/**
	 * Current status of an area: Locked (no interaction), Unlocked (interaction + tasks, not complete), or Complete (fully done).
	 * In point-buy mode: complete only when every task in the area is completed (not just when area is unlocked).
	 * In points-to-complete mode: complete when the area has earned enough points to complete it.
	 */
	public AreaStatus getAreaStatus(String areaId)
	{
		if (!areaGraphService.getUnlockedAreaIds().contains(areaId))
		{
			return AreaStatus.LOCKED;
		}
		if (config.unlockMode() == GridScapeConfig.UnlockMode.POINT_BUY)
		{
			// Unlocked area is complete only when all tasks in that area are completed
			return taskGridServiceProvider.get().isAreaFullyCompleted(areaId) ? AreaStatus.COMPLETE : AreaStatus.UNLOCKED;
		}
		// Points-to-complete: complete when earned enough points in this area
		return completedAreaIds.contains(areaId) ? AreaStatus.COMPLETE : AreaStatus.UNLOCKED;
	}

	/**
	 * Add points earned in a specific area (e.g. from completing a task there).
	 * Also adds to global earned total so they can be spent. When points in area reach threshold, area is marked complete.
	 */
	public void addEarnedInArea(String areaId, int amount)
	{
		if (amount <= 0) return;
		pointsService.addEarned(amount);
		int prev = pointsEarnedInArea.getOrDefault(areaId, 0);
		int next = prev + amount;
		pointsEarnedInArea.put(areaId, next);
		persistPointsPerArea();
		int threshold = getPointsToComplete(areaId);
		if (threshold > 0 && next >= threshold && completedAreaIds.add(areaId))
		{
			persistCompleted();
			log.debug("Area {} completed ({} / {} points)", areaId, next, threshold);
		}
	}

	/** Persists points-per-area as "areaId:points,areaId:points,...". Skips areas with <= 0 points. */
	private void persistPointsPerArea()
	{
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<String, Integer> e : pointsEarnedInArea.entrySet())
		{
			if (e.getValue() <= 0) continue;
			if (sb.length() > 0) sb.append(",");
			sb.append(e.getKey()).append(":").append(e.getValue());
		}
		configManager.setConfiguration(CONFIG_GROUP, KEY_POINTS_PER_AREA, sb.toString());
	}

	/** Persists completed area IDs as comma-separated string. */
	private void persistCompleted()
	{
		String joined = String.join(",", completedAreaIds);
		configManager.setConfiguration(CONFIG_GROUP, KEY_COMPLETED_AREAS, joined);
	}
}

package com.gridscape.points;

import lombok.Getter;
import net.runelite.client.config.ConfigManager;

/**
 * Tracks points earned and spent for GridScape. Persists earned total and spent total via
 * ConfigManager so progress survives restarts. Instantiated only via GridScapePlugin's
 * {@code @Provides} so a single instance is used. Spendable = earnedTotal - spentTotal (used for
 * unlocking areas in point-buy mode).
 */
public class PointsService
{
	private static final String CONFIG_GROUP = com.gridscape.util.GridScapeConfigConstants.STATE_GROUP;
	private static final String KEY_EARNED = "pointsEarnedTotal";
	private static final String KEY_SPENT = "pointsSpentTotal";

	@Getter
	private int earnedTotal;
	@Getter
	private int spentTotal;

	private final ConfigManager configManager;

	public PointsService(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/**
	 * Returns the number of points the player can currently spend (e.g. on unlocking areas).
	 * Never negative.
	 */
	public int getSpendable()
	{
		return Math.max(0, earnedTotal - spentTotal);
	}

	/**
	 * Adds points to the earned total (e.g. from claiming a task). Does nothing if amount <= 0.
	 * Persists to config after update.
	 */
	public void addEarned(int amount)
	{
		if (amount <= 0) return;
		earnedTotal += amount;
		persist();
	}

	/**
	 * Spends points (e.g. to unlock an area). Only succeeds if amount is positive and not greater
	 * than spendable points. Persists to config on success.
	 *
	 * @param amount points to spend
	 * @return true if the spend was applied, false if amount invalid or insufficient spendable
	 */
	public boolean spend(int amount)
	{
		if (amount <= 0 || amount > getSpendable()) return false;
		spentTotal += amount;
		persist();
		return true;
	}

	/**
	 * Loads earned and spent totals from config. Call on plugin start or when loading saved state.
	 */
	public void loadFromConfig()
	{
		String e = configManager.getConfiguration(CONFIG_GROUP, KEY_EARNED);
		String s = configManager.getConfiguration(CONFIG_GROUP, KEY_SPENT);
		earnedTotal = parseInt(e, 0);
		spentTotal = parseInt(s, 0);
	}

	/**
	 * Sets the starting points (e.g. from config). Resets spent to 0 so spendable = starting points.
	 * Used when the user changes "Starting points" in config.
	 */
	public void setStartingPoints(int points)
	{
		earnedTotal = points;
		spentTotal = 0;
		persist();
	}

	/** Writes current earned and spent totals to config. */
	private void persist()
	{
		configManager.setConfiguration(CONFIG_GROUP, KEY_EARNED, earnedTotal);
		configManager.setConfiguration(CONFIG_GROUP, KEY_SPENT, spentTotal);
	}

	/** Parses an integer from config string; returns default if null, empty, or invalid. */
	private static int parseInt(String s, int def)
	{
		if (s == null || s.isEmpty()) return def;
		try
		{
			return Integer.parseInt(s);
		}
		catch (NumberFormatException e)
		{
			return def;
		}
	}
}

package com.gridscape.config;

import com.gridscape.GridScapeConfig;
