/**
 * Small undecorated popup matching task-detail styling; shown when a task-grid ring-completion bonus is awarded.
 */
public final class RingBonusPopup
{
	private static final Color POPUP_BG = GridScapeColors.POPUP_BG;
	private static final Color POPUP_TEXT = GridScapeColors.POPUP_TEXT;
	private static final Color POPUP_BORDER = GridScapeColors.POPUP_BORDER;
	private static final Color BONUS_ACCENT = new Color(120, 200, 120);
	private static final Dimension OK_BUTTON_SIZE = new Dimension(160, 28);

	private RingBonusPopup() {}

	/**
	 * Shows a ring bonus notification, or no-ops if {@code bonusPoints} &lt;= 0.
	 * Safe to call from any thread; display runs on the EDT.
	 *
	 * @param globalGrid   if true, subtitle says "Global task grid"; else uses area display name
	 * @param areaLabel    when {@code globalGrid} is false, shown as "Area: …"
	 */
	public static void showAsync(Frame frameOwner, Component locationRelative, Client client, AudioPlayer audioPlayer,
		int ringNumber, int bonusPoints, boolean globalGrid, String areaLabel)
	{
		if (bonusPoints <= 0) return;
		SwingUtilities.invokeLater(() -> showInternal(frameOwner, locationRelative, client, audioPlayer,
			ringNumber, bonusPoints, globalGrid, areaLabel));
	}

	private static void showInternal(Frame frameOwner, Component locationRelative, Client client, AudioPlayer audioPlayer,
		int ringNumber, int bonusPoints, boolean globalGrid, String areaLabel)
	{
		if (audioPlayer != null && client != null)
			GridScapeSounds.play(audioPlayer, GridScapeSounds.COINS_JINGLE, client);

		JDialog detail = new JDialog(frameOwner, "Ring bonus", false);
		detail.setUndecorated(true);
		GridScapeSwingUtil.registerEscapeToClose(detail);

		JPanel content = new JPanel(new BorderLayout(8, 8));
		content.setBackground(POPUP_BG);
		content.setBorder(new CompoundBorder(
			new LineBorder(POPUP_BORDER, 2),
			new EmptyBorder(12, 14, 12, 14)));

		JPanel header = new JPanel(new BorderLayout(4, 0));
		header.setOpaque(false);
		JLabel titleLabel = new JLabel("Ring " + ringNumber + " complete");
		titleLabel.setForeground(POPUP_TEXT);
		titleLabel.setFont(titleLabel.getFont().deriveFont(Font.BOLD, 13f));
		header.add(titleLabel, BorderLayout.CENTER);
		java.awt.image.BufferedImage xBtnImg = ImageUtil.loadImageResource(GridScapePlugin.class, "x_button.png");
		JButton closeBtn = GridScapeSwingUtil.newPopupButtonWithIcon(xBtnImg, POPUP_TEXT);
		closeBtn.addActionListener(e -> {
			if (audioPlayer != null && client != null)
				GridScapeSounds.play(audioPlayer, GridScapeSounds.BUTTON_PRESS, client);
			detail.dispose();
		});
		header.add(closeBtn, BorderLayout.EAST);
		content.add(header, BorderLayout.NORTH);

		JPanel body = new JPanel();
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setOpaque(false);

		String scope = globalGrid
			? "Global task grid"
			: ("Area: " + (areaLabel != null && !areaLabel.trim().isEmpty() ? areaLabel.trim() : "—"));
		JLabel scopeLabel = new JLabel("<html>" + scope + "</html>");
		scopeLabel.setForeground(POPUP_TEXT);
		body.add(scopeLabel);
		body.add(new JLabel(" "));

		JLabel bonusLabel = new JLabel("<html><b>+" + bonusPoints + "</b> bonus points</html>");
		bonusLabel.setForeground(BONUS_ACCENT);
		bonusLabel.setFont(bonusLabel.getFont().deriveFont(Font.BOLD, 14f));
		body.add(bonusLabel);

		java.awt.image.BufferedImage buttonRect = ImageUtil.loadImageResource(GridScapePlugin.class, "empty_button_rectangle.png");
		JButton okBtn = GridScapeSwingUtil.newRectangleButton("OK", buttonRect, POPUP_TEXT);
		okBtn.setPreferredSize(OK_BUTTON_SIZE);
		okBtn.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(new JLabel(" "));
		okBtn.addActionListener(e -> {
			if (audioPlayer != null && client != null)
				GridScapeSounds.play(audioPlayer, GridScapeSounds.BUTTON_PRESS, client);
			detail.dispose();
		});
		body.add(okBtn);

		content.add(body, BorderLayout.CENTER);
		detail.setContentPane(content);
		detail.getRootPane().setBorder(new LineBorder(POPUP_BORDER, 2));
		detail.addWindowFocusListener(new java.awt.event.WindowAdapter()
		{
			@Override
			public void windowLostFocus(java.awt.event.WindowEvent e)
			{
				SwingUtilities.invokeLater(() -> {
					if (detail.isDisplayable()) detail.dispose();
				});
			}
		});
		detail.pack();
		if (locationRelative != null)
			detail.setLocationRelativeTo(locationRelative);
		else if (client != null && client.getCanvas() != null)
			detail.setLocationRelativeTo(client.getCanvas());
		detail.setVisible(true);
		detail.requestFocusInWindow();
	}
}

package com.gridscape.util;

import java.awt.Component;
import java.awt.GraphicsDevice;
import java.awt.GraphicsEnvironment;
import java.awt.Rectangle;
import java.awt.event.ComponentAdapter;
import java.awt.event.ComponentEvent;
import javax.swing.JDialog;
import net.runelite.client.config.ConfigManager;

/**
 * Persists floating panel bounds in {@link GridScapeConfigConstants#STATE_GROUP} so dialogs reopen
 * where the user left them; cleared on progress reset.
 */
public final class PanelBoundsStore
{
	private PanelBoundsStore() {}

	private static final int MIN_W = 80;
	private static final int MIN_H = 60;

	public static final String KEY_WORLD_UNLOCK = "panelBoundsWorldUnlock";
	public static final String KEY_GLOBAL_TASKS = "panelBoundsGlobalTasks";
	public static final String KEY_AREA_TASK_GRID = "panelBoundsAreaTaskGrid";
	public static final String KEY_GOALS = "panelBoundsGoals";

	public static void applyBounds(JDialog dialog, ConfigManager cm, String key, Component canvas)
	{
		String raw = cm.getConfiguration(GridScapeConfigConstants.STATE_GROUP, key);
		Rectangle r = parseRectangle(raw);
		if (r != null && r.width >= MIN_W && r.height >= MIN_H)
		{
			Rectangle fitted = constrainToVisible(r);
			if (fitted != null)
			{
				dialog.setBounds(fitted);
				return;
			}
		}
		dialog.setLocationRelativeTo(canvas);
	}

	public static void installPersistence(JDialog dialog, ConfigManager cm, String key)
	{
		Runnable save = () -> {
			if (!dialog.isShowing())
			{
				return;
			}
			Rectangle b = dialog.getBounds();
			cm.setConfiguration(GridScapeConfigConstants.STATE_GROUP, key,
				b.x + "," + b.y + "," + b.width + "," + b.height);
		};
		dialog.addComponentListener(new ComponentAdapter()
		{
			@Override
			public void componentMoved(ComponentEvent e)
			{
				save.run();
			}

			@Override
			public void componentResized(ComponentEvent e)
			{
				save.run();
			}
		});
	}

	public static void clearPanelBounds(ConfigManager cm)
	{
		cm.unsetConfiguration(GridScapeConfigConstants.STATE_GROUP, KEY_WORLD_UNLOCK);
		cm.unsetConfiguration(GridScapeConfigConstants.STATE_GROUP, KEY_GLOBAL_TASKS);
		cm.unsetConfiguration(GridScapeConfigConstants.STATE_GROUP, KEY_AREA_TASK_GRID);
		cm.unsetConfiguration(GridScapeConfigConstants.STATE_GROUP, KEY_GOALS);
	}

	private static Rectangle parseRectangle(String raw)
	{
		if (raw == null || raw.isEmpty())
		{
			return null;
		}
		try
		{
			String[] p = raw.split(",");
			if (p.length != 4)
			{
				return null;
			}
			int x = Integer.parseInt(p[0].trim());
			int y = Integer.parseInt(p[1].trim());
			int w = Integer.parseInt(p[2].trim());
			int h = Integer.parseInt(p[3].trim());
			return new Rectangle(x, y, w, h);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private static Rectangle virtualScreenBounds()
	{
		GraphicsEnvironment ge = GraphicsEnvironment.getLocalGraphicsEnvironment();
		Rectangle union = null;
		for (GraphicsDevice gd : ge.getScreenDevices())
		{
			Rectangle b = gd.getDefaultConfiguration().getBounds();
			union = union == null ? new Rectangle(b) : union.union(b);
		}
		return union;
	}

	/** Returns a position/size on the virtual screen, or null if the saved rect is unusable. */
	private static Rectangle constrainToVisible(Rectangle r)
	{
		Rectangle union = virtualScreenBounds();
		if (union == null || !union.intersects(r))
		{
			return null;
		}
		Rectangle inter = r.intersection(union);
		if (inter.width * inter.height < MIN_W * MIN_H / 4)
		{
			return null;
		}
		int w = r.width;
		int h = r.height;
		int x = r.x;
		int y = r.y;
		x = Math.max(union.x, Math.min(x, union.x + union.width - w));
		y = Math.max(union.y, Math.min(y, union.y + union.height - h));
		if (x + w > union.x + union.width)
		{
			x = union.x + union.width - w;
		}
		if (y + h > union.y + union.height)
		{
			y = union.y + union.height - h;
		}
		if (x < union.x)
		{
			x = union.x;
		}
		if (y < union.y)
		{
			y = union.y;
		}
		return new Rectangle(x, y, w, h);
	}
}

package com.gridscape.util;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Point;
import java.awt.Rectangle;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JViewport;
import javax.swing.Timer;
import java.util.function.Consumer;

/**
 * Smooth zoom + scroll focus after claiming a grid tile (default 100ms).
 */
public final class GridClaimFocusAnimation
{
	public static final int CLAIM_FOCUS_DURATION_MS = 100;
	private static final int STEPS = 10;

	private GridClaimFocusAnimation() {}

	/** Client properties on each grid cell so we can read real {@link Component#getBounds()} after layout. */
	public static final String GRID_CELL_ROW_KEY = "GridScape.gridRow";
	public static final String GRID_CELL_COL_KEY = "GridScape.gridCol";

	public static void putGridCellKeys(JComponent c, int row, int col)
	{
		c.putClientProperty(GRID_CELL_ROW_KEY, row);
		c.putClientProperty(GRID_CELL_COL_KEY, col);
	}

	private static boolean matchesGridCell(JComponent c, int row, int col)
	{
		Object r = c.getClientProperty(GRID_CELL_ROW_KEY);
		Object co = c.getClientProperty(GRID_CELL_COL_KEY);
		if (!(r instanceof Integer) || !(co instanceof Integer))
			return false;
		return ((Integer) r).intValue() == row && ((Integer) co).intValue() == col;
	}

	private static Component findGridCellChild(JPanel gridPanel, int row, int col)
	{
		for (Component c : gridPanel.getComponents())
		{
			if (c instanceof JComponent && matchesGridCell((JComponent) c, row, col))
				return c;
		}
		return null;
	}

	private static int[] viewExtentsForScrolling(JViewport viewport, JPanel gridPanel, int ringExtent, int tileSize,
		int cellPaddingTotal)
	{
		Dimension vs = viewport.getViewSize();
		Dimension pref = gridPanel.getPreferredSize();
		int span = 2 * ringExtent + 1;
		int cellW = tileSize + cellPaddingTotal;
		int logicalW = span * cellW;
		int logicalH = span * cellW;
		int viewW = Math.max(Math.max(vs.width, pref.width), logicalW);
		int viewH = Math.max(Math.max(vs.height, pref.height), logicalH);
		return new int[] { viewW, viewH };
	}

	private static Point centerViewportOnPoint(int cx, int cy, int vw, int vh, int viewW, int viewH)
	{
		int maxX = Math.max(0, viewW - vw);
		int maxY = Math.max(0, viewH - vh);
		int vpx = Math.max(0, Math.min(cx - vw / 2, maxX));
		int vpy = Math.max(0, Math.min(cy - vh / 2, maxY));
		return new Point(vpx, vpy);
	}

	/**
	 * Centers the viewport on the grid cell at {@code (row,col)}. Prefer the laid-out bounds of the cell
	 * component (see {@link #putGridCellKeys}) — {@link java.awt.GridBagLayout} collapses empty rows, so
	 * {@code gy * cellH} does not match real Y positions and vertical panning would fail without this.
	 * Falls back to ring geometry when the cell is missing or not yet laid out.
	 *
	 * @param ringExtent half the grid width in cells minus center (same as maxRing / center index)
	 */
	public static Point computeViewPositionForTile(JViewport viewport, JPanel gridPanel, int row, int col,
		int ringExtent, int tileSize, int cellPaddingTotal)
	{
		if (viewport == null || gridPanel == null)
			return new Point(0, 0);

		Container scrollParent = viewport.getParent();
		if (scrollParent != null)
			scrollParent.validate();
		viewport.validate();
		gridPanel.validate();

		int vw = viewport.getExtentSize().width;
		int vh = viewport.getExtentSize().height;
		if (vw <= 0 || vh <= 0)
			return new Point(0, 0);

		int[] extents = viewExtentsForScrolling(viewport, gridPanel, ringExtent, tileSize, cellPaddingTotal);
		int viewW = extents[0];
		int viewH = extents[1];

		Component target = findGridCellChild(gridPanel, row, col);
		if (target != null)
		{
			Rectangle b = target.getBounds();
			if (b.width > 0 && b.height > 0)
			{
				int cx = b.x + b.width / 2;
				int cy = b.y + b.height / 2;
				return centerViewportOnPoint(cx, cy, vw, vh, viewW, viewH);
			}
		}

		int gx = col + ringExtent;
		int gy = ringExtent - row;
		int cellW = tileSize + cellPaddingTotal;
		int cellH = cellW;
		int px = gx * cellW;
		int py = gy * cellH;
		return centerViewportOnPoint(px + cellW / 2, py + cellH / 2, vw, vh, viewW, viewH);
	}

	/**
	 * Animates zoom from start to end over {@link #CLAIM_FOCUS_DURATION_MS} with smoothstep, calling
	 * {@code refresh} after each step. If zoom span is negligible, runs one refresh and completes.
	 */
	public static void animateZoomToClaim(float zoomStart, float zoomEnd, float zoomMin, float zoomMax,
		Consumer<Float> setZoom, Runnable refresh, Runnable onComplete)
	{
		float z0 = Math.max(zoomMin, Math.min(zoomMax, zoomStart));
		float z1 = Math.max(zoomMin, Math.min(zoomMax, zoomEnd));
		if (Math.abs(z1 - z0) < 0.0005f)
		{
			if (refresh != null)
			{
				refresh.run();
			}
			if (onComplete != null)
			{
				onComplete.run();
			}
			return;
		}
		final int[] step = { 0 };
		int delay = Math.max(1, CLAIM_FOCUS_DURATION_MS / STEPS);
		Timer timer = new Timer(delay, null);
		timer.addActionListener(e -> {
			step[0]++;
			float p = Math.min(1f, step[0] / (float) STEPS);
			float t = p * p * (3f - 2f * p);
			float z = z0 + (z1 - z0) * t;
			z = Math.max(zoomMin, Math.min(zoomMax, z));
			setZoom.accept(z);
			if (refresh != null)
			{
				refresh.run();
			}
			if (step[0] >= STEPS)
			{
				timer.stop();
				setZoom.accept(z1);
				if (refresh != null)
				{
					refresh.run();
				}
				if (onComplete != null)
				{
					onComplete.run();
				}
			}
		});
		timer.setRepeats(true);
		timer.start();
	}
}

package com.gridscape.util;

