package com.gridscape.util;

import java.awt.Graphics;
import java.awt.image.BufferedImage;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.client.util.ImageUtil;

/**
 * Caches {@link BufferedImage} scales produced with {@link ImageUtil#resizeImage} to avoid
 * {@link Image#getScaledInstance}, which can defer work to the image consumer and repeat work every paint.
 */
public final class ScaledImageCache
{
	private static final int MAX_ENTRIES = 512;

	private static final Map<CacheKey, BufferedImage> CACHE = new LinkedHashMap<CacheKey, BufferedImage>(256, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<CacheKey, BufferedImage> eldest)
		{
			return size() > MAX_ENTRIES;
		}
	};

	private static final class CacheKey
	{
		final BufferedImage src;
		final int w;
		final int h;

		CacheKey(BufferedImage src, int w, int h)
		{
			this.src = src;
			this.w = w;
			this.h = h;
		}

		@Override
		public boolean equals(Object o)
		{
			if (this == o) return true;
			if (!(o instanceof CacheKey)) return false;
			CacheKey k = (CacheKey) o;
			return src == k.src && w == k.w && h == k.h;
		}

		@Override
		public int hashCode()
		{
			return System.identityHashCode(src) ^ (w * 65537) ^ (h * 131071);
		}
	}

	private ScaledImageCache()
	{
	}

	/**
	 * Returns a scaled copy of {@code src} with dimensions {@code w} x {@code h}, or {@code src}
	 * if dimensions already match. May return a cached instance.
	 */
	public static BufferedImage getScaled(BufferedImage src, int w, int h)
	{
		if (src == null || w <= 0 || h <= 0)
		{
			return null;
		}
		int sw = src.getWidth();
		int sh = src.getHeight();
		if (sw <= 0 || sh <= 0)
		{
			return null;
		}
		if (w == sw && h == sh)
		{
			return src;
		}
		synchronized (CACHE)
		{
			CacheKey key = new CacheKey(src, w, h);
			BufferedImage cached = CACHE.get(key);
			if (cached != null)
			{
				return cached;
			}
			BufferedImage out = ImageUtil.resizeImage(src, w, h);
			if (out != null)
			{
				CACHE.put(key, out);
			}
			return out;
		}
	}

	/**
	 * Draws {@code src} scaled to {@code w} x {@code h} at ({@code x}, {@code y}).
	 */
	public static void drawScaled(Graphics g, BufferedImage src, int x, int y, int w, int h)
	{
		BufferedImage scaled = getScaled(src, w, h);
		if (scaled != null)
		{
			g.drawImage(scaled, x, y, null);
		}
	}
}

package com.gridscape.util;

import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/**
 * Paints frontier fog using four quadrant images (top/bottom × left/right corners).
 * Parameters {@code north,east,south,west} are geographic (row - 1 = north, row + 1 = south, etc.), matching
 * {@link com.gridscape.util.FrontierFogHelpers}. Task and world-unlock grids lay out with
 * {@code gridy = maxRing - row}, so on screen geographic south (row + 1) sits above the cell and geographic north
 * (row - 1) below. Corner quadrants follow Java screen coords (y-down): the top edge of the cell uses geographic
 * <em>south</em> (neighbor above on screen); the bottom edge uses geographic <em>north</em> (neighbor below on screen).
 * <p>
 * When corner assets are full-tile images (all four decorative corners in one bitmap), each file is cropped to the
 * quadrant matching its name before scaling. Images smaller than 64×64 px (either dimension) are scaled without
 * cropping (dedicated corner sprites).
 */
public final class FogTileCompositor
{
	/** Source images at least this size on both axes are treated as full-tile textures and cropped per quadrant. */
	private static final int MIN_CROP_DIMENSION = 64;

	private FogTileCompositor() {}

	/**
	 * @param north east south west geographic cardinals from {@link com.gridscape.util.FrontierFogHelpers}
	 *        (neighbor at row - 1 / row + 1 / col +/- 1).
	 */
	public static void paintFogQuadrants(Graphics g, int w, int h,
		boolean north, boolean east, boolean south, boolean west,
		BufferedImage topLeft, BufferedImage topRight, BufferedImage bottomLeft, BufferedImage bottomRight)
	{
		if (w <= 0 || h <= 0) return;
		int hw = w / 2;
		int hh = h / 2;
		// Map geographic neighbors to screen edges (see class javadoc): top ← south, bottom ← north, left ← west, right ← east.
		boolean drawTL = south || west;
		boolean drawTR = south || east;
		boolean drawBL = north || west;
		boolean drawBR = north || east;
		if (!drawTL && !drawTR && !drawBL && !drawBR) return;

		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			if (drawTL) drawCornerQuadrant(g2, topLeft, Quadrant.TOP_LEFT, 0, 0, hw, hh);
			if (drawTR) drawCornerQuadrant(g2, topRight, Quadrant.TOP_RIGHT, hw, 0, hw, hh);
			if (drawBL) drawCornerQuadrant(g2, bottomLeft, Quadrant.BOTTOM_LEFT, 0, hh, hw, hh);
			if (drawBR) drawCornerQuadrant(g2, bottomRight, Quadrant.BOTTOM_RIGHT, hw, hh, hw, hh);
		}
		finally
		{
			g2.dispose();
		}
	}

	private enum Quadrant
	{
		TOP_LEFT, TOP_RIGHT, BOTTOM_LEFT, BOTTOM_RIGHT
	}

	private static void drawCornerQuadrant(Graphics2D g2, BufferedImage src, Quadrant q, int dx, int dy, int dw, int dh)
	{
		if (src == null || dw <= 0 || dh <= 0) return;
		int iw = src.getWidth();
		int ih = src.getHeight();
		if (iw <= 0 || ih <= 0) return;

		int sx = 0, sy = 0, sw = iw, sh = ih;
		if (iw >= MIN_CROP_DIMENSION && ih >= MIN_CROP_DIMENSION)
		{
			sw = iw / 2;
			sh = ih / 2;
			switch (q)
			{
				case TOP_LEFT:
					sx = 0;
					sy = 0;
					break;
				case TOP_RIGHT:
					sx = sw;
					sy = 0;
					break;
				case BOTTOM_LEFT:
					sx = 0;
					sy = sh;
					break;
				case BOTTOM_RIGHT:
					sx = sw;
					sy = sh;
					break;
			}
		}
		g2.drawImage(src, dx, dy, dx + dw, dy + dh, sx, sy, sx + sw, sy + sh, null);
	}
}

package com.gridscape.util;

import com.gridscape.GridScapePlugin;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.util.ImageUtil;

/**
 * OSRS-style tiled frame: {@code fill_color} in the center and {@code border_*} strips on edges.
 * Corner images are optional (nullable). Content should use {@link #getChromeInsets()} for padding.
 * Asset paths match {@link com.gridscape.GridScapePlugin} resources ({@code fill_color.png}, etc.).
 */
public final class GridScapeFrameChromePanel extends JPanel
{
	private static final Color FALLBACK_FILL = new Color(0x54, 0x4D, 0x41);

	private final BufferedImage fill;
	private final BufferedImage tl;
	private final BufferedImage tr;
	private final BufferedImage bl;
	private final BufferedImage br;
	private final BufferedImage bTop;
	private final BufferedImage bBottom;
	private final BufferedImage bLeft;
	private final BufferedImage bRight;
	private final Insets chromeInsets;

	/** Loads standard frame assets from {@link GridScapePlugin} resources. */
	public static GridScapeFrameChromePanel createFromResources()
	{
		return new GridScapeFrameChromePanel(
			ImageUtil.loadImageResource(GridScapePlugin.class, "fill_color.png"),
			ImageUtil.loadImageResource(GridScapePlugin.class, "top_left_corner.png"),
			ImageUtil.loadImageResource(GridScapePlugin.class, "top_right_corner.png"),
			ImageUtil.loadImageResource(GridScapePlugin.class, "bottom_left_corner.png"),
			ImageUtil.loadImageResource(GridScapePlugin.class, "bottom_right_corner.png"),
			ImageUtil.loadImageResource(GridScapePlugin.class, "border_top.png"),
			ImageUtil.loadImageResource(GridScapePlugin.class, "border_bottom.png"),
			ImageUtil.loadImageResource(GridScapePlugin.class, "border_left.png"),
			ImageUtil.loadImageResource(GridScapePlugin.class, "border_right.png"));
	}

	/**
	 * Chrome panel with an opaque-false inner content panel already inset by {@link #getChromeInsets()}.
	 * Use the returned inner panel as the parent for header / body / south content.
	 */
	public static GridScapeFrameChromePanel wrapContent(JPanel inner)
	{
		GridScapeFrameChromePanel chrome = createFromResources();
		chrome.setLayout(new BorderLayout(0, 0));
		inner.setOpaque(false);
		Insets insets = chrome.getChromeInsets();
		inner.setBorder(new EmptyBorder(insets.top, insets.left, insets.bottom, insets.right));
		chrome.add(inner, BorderLayout.CENTER);
		return chrome;
	}

	public GridScapeFrameChromePanel(BufferedImage fill, BufferedImage tl, BufferedImage tr, BufferedImage bl, BufferedImage br,
		BufferedImage bTop, BufferedImage bBottom, BufferedImage bLeft, BufferedImage bRight)
	{
		this.fill = fill;
		this.tl = tl;
		this.tr = tr;
		this.bl = bl;
		this.br = br;
		this.bTop = bTop;
		this.bBottom = bBottom;
		this.bLeft = bLeft;
		this.bRight = bRight;
		int tlW = tl != null ? tl.getWidth() : 0;
		int tlH = tl != null ? tl.getHeight() : 0;
		int trW = tr != null ? tr.getWidth() : 0;
		int trH = tr != null ? tr.getHeight() : 0;
		int blW = bl != null ? bl.getWidth() : 0;
		int blH = bl != null ? bl.getHeight() : 0;
		int brW = br != null ? br.getWidth() : 0;
		int brH = br != null ? br.getHeight() : 0;
		int tH = bTop != null ? bTop.getHeight() : 0;
		int bH = bBottom != null ? bBottom.getHeight() : 0;
		int lW = bLeft != null ? bLeft.getWidth() : 0;
		int rW = bRight != null ? bRight.getWidth() : 0;
		int top = Math.max(Math.max(tlH, trH), tH);
		int bot = Math.max(Math.max(blH, brH), bH);
		int left = Math.max(Math.max(tlW, blW), lW);
		int right = Math.max(Math.max(trW, brW), rW);
		chromeInsets = new Insets(top, left, bot, right);
		setOpaque(false);
	}

	public Insets getChromeInsets()
	{
		return new Insets(chromeInsets.top, chromeInsets.left, chromeInsets.bottom, chromeInsets.right);
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
			paintFrame(g2, getWidth(), getHeight());
		}
		finally
		{
			g2.dispose();
		}
		super.paintComponent(g);
	}

	private void paintFrame(Graphics2D g, int w, int h)
	{
		if (w <= 0 || h <= 0)
			return;
		int tlW = tl != null ? tl.getWidth() : 0;
		int tlH = tl != null ? tl.getHeight() : 0;
		int trW = tr != null ? tr.getWidth() : 0;
		int trH = tr != null ? tr.getHeight() : 0;
		int blW = bl != null ? bl.getWidth() : 0;
		int blH = bl != null ? bl.getHeight() : 0;
		int brW = br != null ? br.getWidth() : 0;
		int brH = br != null ? br.getHeight() : 0;
		int tH = bTop != null ? bTop.getHeight() : 1;
		int bH = bBottom != null ? bBottom.getHeight() : 1;
		int lW = bLeft != null ? bLeft.getWidth() : 1;
		int rW = bRight != null ? bRight.getWidth() : 1;

		int leftInset = chromeInsets.left;
		int rightInset = chromeInsets.right;
		int topInset = chromeInsets.top;
		int bottomInset = chromeInsets.bottom;
		int innerW = w - leftInset - rightInset;
		int innerH = h - topInset - bottomInset;
		if (innerW > 0 && innerH > 0)
		{
			if (fill != null)
				tileImage(g, fill, leftInset, topInset, innerW, innerH);
			else
			{
				g.setColor(FALLBACK_FILL);
				g.fillRect(leftInset, topInset, innerW, innerH);
			}
		}

		if (bTop != null && w > tlW + trW)
		{
			int segW = w - tlW - trW;
			if (segW > 0)
				tileImage(g, bTop, tlW, 0, segW, Math.max(1, tH));
		}
		if (bBottom != null && w > blW + brW)
		{
			int segW = w - blW - brW;
			int bh = Math.max(1, bH);
			if (segW > 0)
				tileImage(g, bBottom, blW, h - bh, segW, bh);
		}
		if (bLeft != null && h > tlH + blH)
		{
			int segH = h - tlH - blH;
			if (segH > 0)
				tileImage(g, bLeft, 0, tlH, Math.max(1, lW), segH);
		}
		if (bRight != null && h > trH + brH)
		{
			int segH = h - trH - brH;
			int rw = Math.max(1, rW);
			if (segH > 0)
				tileImage(g, bRight, w - rw, trH, rw, segH);
		}

		if (tl != null)
			g.drawImage(tl, 0, 0, null);
		if (tr != null)
			g.drawImage(tr, w - trW, 0, null);
		if (bl != null)
			g.drawImage(bl, 0, h - blH, null);
		if (br != null)
			g.drawImage(br, w - brW, h - brH, null);
	}

	private static void tileImage(Graphics g, BufferedImage tile, int dx, int dy, int regionW, int regionH)
	{
		if (tile == null || regionW <= 0 || regionH <= 0)
			return;
		int tw = tile.getWidth();
		int th = tile.getHeight();
		if (tw <= 0 || th <= 0)
			return;
		for (int py = 0; py < regionH; py += th)
		{
			int sh = Math.min(th, regionH - py);
			for (int px = 0; px < regionW; px += tw)
			{
				int sw = Math.min(tw, regionW - px);
				g.drawImage(tile, dx + px, dy + py, dx + px + sw, dy + py + sh, 0, 0, sw, sh, null);
			}
		}
	}
}

package com.gridscape.util;

import java.util.HashSet;
import java.util.Set;

/**
 * Helpers for parsing config values (e.g. comma-separated lists/sets).
 */
public final class ConfigParsing
{
	private ConfigParsing() {}

	/**
	 * Parses a comma-separated string into a set of trimmed, non-empty tokens.
	 * Null or empty input returns an empty set.
	 */
	public static Set<String> parseCommaSeparatedSet(String raw)
	{
		if (raw == null || raw.isEmpty())
			return new HashSet<>();
		Set<String> out = new HashSet<>();
		for (String part : raw.split(","))
		{
			String t = part.trim();
			if (!t.isEmpty())
				out.add(t);
		}
		return out;
	}

	/**
	 * Joins a set of strings with comma (no spaces). Used for persisting back to config.
	 */
	public static String joinComma(Set<String> set)
	{
		if (set == null || set.isEmpty())
			return "";
		return String.join(",", set);
	}
}

